#[inline] pub fn find_app_asset(id: &[u8]) -> Option<&'static VectorAsset> {
    for a in APP_ASSETS { if a.id == id { return Some(a); } } None
}
#[inline] pub fn app_shapes(asset: &VectorAsset) -> &'static [VectorShape] {
    let (s, e) = (asset.start as usize, asset.start as usize + asset.len as usize);
    APP_SHAPES.get(s..e).unwrap_or(&[])
}
